/** 🔏️ The digest of everything a project reads from one walk: the roster, the modules it compiled and the generated outputs those modules import. */
function walkAnswerV1(cache, workspaceRoot, value) {
  const compiled = [...(cache.compiledNames.get(value) ?? [])].sort();
  const generated = compiled.map(name => [name, cache.generatedImports.get(resolve(workspaceRoot, name.slice("{workspaceRoot}/".length))) ?? []]);
  return createHash("sha256").update(JSON.stringify([value, compiled, generated])).digest("hex");
}

